    if(!same){if(receipt.weak)weak_free(receipt.weak);receipt={};receipt.weak=weak_new(controller,false);}
    if(!receipt.weak||weak_get(receipt.weak)!=controller){if(receipt.weak)weak_free(receipt.weak);receipt={};return;}
